import numpy as np
from sklearn.ensemble import RandomForestClassifier
from sklearn.linear_model import LogisticRegression

def honest_forest(X, y, n_train, ms, depths):
    X = np.asarray(X, dtype=float); y = np.asarray(y)
    Xtr, ytr, Xte, yte = X[:n_train], y[:n_train], X[n_train:], y[n_train:]
    best = None
    for m in ms:
        for d in depths:
            f = RandomForestClassifier(n_estimators=50, max_features=m, max_depth=d,
                                       oob_score=True, random_state=0).fit(Xtr, ytr)
            if best is None or f.oob_score_ > best[0]:
                best = (f.oob_score_, m, d, f)
    _, m, d, f = best
    logit = LogisticRegression(max_iter=1000).fit(Xtr, ytr)
    return m, d, round(float(f.score(Xte, yte)), 4), round(float(logit.score(Xte, yte)), 4)
